KG42.register("rules-7c4e4b80253411303d0956f3",{"id":"49-residential_shared_storage_market::v141-c-R004","paper":"49-residential_shared_storage_market","record":{"rule_id":"v141-c-R004","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"An energy buyer's decision to purchase energy from the P2P market or the power grid depends on the price signal. Scope: Energy buyers choosing between P2P-market and power-grid energy purchases. Energy sellers and buyers may trade freely with one another and reach a bilaterally satisfactory transaction result. Scope: Exchanges between energy sellers and energy buyers in the proposed P2P market. Sellers are forbidden to buy energy from the grid and sell energy to the P2P market simultaneously. Scope: Sellers' P2P sales under the paper's price-setting restriction.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.price_signal","execution.energy_trade"],"E":[{"edge_id":"v141-c-R004-E001","source":"execution.energy_trade","target":"coordination.price_signal","type":"conditional_on","constraint_ids":["v141-c-R004-C001"],"evidence_ids":["v141-b-g01-E06"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Energy buyers choosing between P2P-market and power-grid energy purchases. | Exchanges between energy sellers and energy buyers in the proposed P2P market. | Sellers' P2P sales under the paper's price-setting restriction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E06","v141-b-g02-e040"]},"x":[{"variable_id":"v141-c-R004-x-p_sb","symbol":"p^{t}_{sb}","meaning":"P2P transaction amount between seller s and buyer b in period t; buyer-side P2P purchase decision variable in the buyer's energy-cost minimization.","kind":"operational","domain":"\\mathbb{R}_{\\ge 0}","unit":null,"indices":["s∈S","b∈B","t∈T"],"evidence_ids":["v141-b-g01-E12","v141-b-g01-E13","v141-b-g01-E15","v141-b-g01-E21"]},{"variable_id":"v141-c-R004-x-p_bg","symbol":"p^{t}_{bg}","meaning":"Energy purchased from the power grid by buyer b in period t; buyer-side grid-purchase decision variable in the buyer's energy-cost minimization.","kind":"operational","domain":"\\mathbb{R}_{\\ge 0}","unit":null,"indices":["b∈B","t∈T"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E21"]}],"theta":[{"parameter_id":"v141-c-R004-theta-rho","symbol":"\\rho^{t}_{sb}","meaning":"P2P transaction price signal between seller s and buyer b in period t. The source lists rho among variables but states it is endogenously determined by market equilibrium, beyond a single participant's control, and treats it as a parameter when deriving participant KKT conditions; within R004's individual buyer execution decision it is therefore represented as a price-signal parameter.","value":{"kind":"symbolic","number_value":null,"text_value":"endogenous P2P transaction price signal"},"unit":null,"indices":["s∈S","b∈B","t∈T"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E15","v141-b-g01-E21","v141-b-g02-e024","v141-b-g02-e028"]},{"parameter_id":"v141-c-R004-theta-lambda_buy","symbol":"\\lambda^{t}_{buy}","meaning":"Time-and-level-of-use (TLOU) grid electricity price faced by buyer b in period t.","value":{"kind":"symbolic","number_value":null,"text_value":"TLOU price of buyer b in period t"},"unit":null,"indices":["b∈B","t∈T"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E17","v141-b-g01-E21"]},{"parameter_id":"v141-c-R004-theta-Delta_t","symbol":"\\Delta t","meaning":"Duration of a period, used to scale the P2P and grid purchase cost in the buyer's energy-cost minimization.","value":{"kind":"symbolic","number_value":null,"text_value":"period duration"},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E15","v141-b-g01-E21"]}],"phi":[{"constraint_id":"v141-c-R004-C001","kind":"logical","role":"core","statement":"An energy buyer's decision to purchase energy from the P2P market or the power grid depends on the price signal. Scope: Energy buyers choosing between P2P-market and power-grid energy purchases.","expression":"\\min_{p^{t}_{sb},p^{t}_{bg}}\\sum_{t\\in T}\\left(\\sum_{s\\in S}\\rho^{t}_{sb}p^{t}_{sb}+\\lambda^{t}_{buy}p^{t}_{bg}\\right)\\Delta t","formalization_origin":"source","template_id":null,"members":["execution.energy_trade","coordination.price_signal"],"variable_refs":["v141-c-R004-x-p_sb","v141-c-R004-x-p_bg"],"parameter_refs":["v141-c-R004-theta-rho","v141-c-R004-theta-lambda_buy","v141-c-R004-theta-Delta_t"],"evidence_ids":["v141-b-g01-E06","v141-b-g01-E13","v141-b-g01-E15"]},{"constraint_id":"v141-c-R004-C002","kind":"procedural","role":"core","statement":"Energy sellers and buyers may trade freely with one another and reach a bilaterally satisfactory transaction result. Scope: Exchanges between energy sellers and energy buyers in the proposed P2P market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E03"]},{"constraint_id":"v141-c-R004-C003","kind":"procedural","role":"core","statement":"Sellers are forbidden to buy energy from the grid and sell energy to the P2P market simultaneously. Scope: Sellers' P2P sales under the paper's price-setting restriction.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e040"]}],"pi":[{"evidence_id":"v141-b-g01-E03","location":{"location_id":"src-4c60176b12-p04-c2r2__v141-a-M01-participation","page":4,"printed_page":null,"section":"2 System configuration","anchor_text":"b­ nt The remainder of the paper is organized as follows. Section 2 in­ troduces a representative sy","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The most representative structure of the peer-to-peer energy trading market with shared energy storage units is shown in Fig. 1. In such a P2P market, a participant who has excessive energy and sells energy to other participants or the power grid is defined as a typical energy seller, e.g., a rooftop PV plant. A participant who consumes energy and buys energy from energy sellers or power grid is identified as a typical energy buyer, e.g., a community. Energy sellers and buyers in the P2P market can trade with each other freely and reach a bilaterally satisfactory transaction result. The solid arrows present the P2P transaction between typical energy sellers and energy buyers. All participants are connected with the local distribution network and the energy trading can be finished through physical power transmission lines."},{"evidence_id":"v141-b-g01-E06","location":{"location_id":"src-4c60176b12-p05-c1r2__v141-a-M01-participation","page":5,"printed_page":null,"section":"2.2 Energy buyers","anchor_text":"in the P2P transaction market or trade with power utility according to de the price signal. Energy s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Energy buyers consist of participants who consume energy, e.g., residential community, business building, shopping mall. We consider the residential community in this paper. Modeling the behavior of residential energy consumers requires both financial and emotional factors, integrating the economic and motivational psychology[56]. Besides, the ideal model is not always consistent with the real-world situation. So we choose the energy cost, which is a conspicuous and acceptable criterion to model consumer behavior. Each energy buyer, whose goal is to minimize the expenditure on energy purchase, can buy energy from the P2P market or power grid depending on the price signal. Besides, multiple buyers share the capacity use right of the SES, which provides the buyers with more flexible energy consumption management. They can use SES and adjust their charging/discharging strategy according to the electricity price on the premise of meeting the current energy deficit. To simplify the problem and show the operation of our P2P market, the initial energy demand of each energy buyer is fixed."},{"evidence_id":"v141-b-g02-e040","location":{"location_id":"src-4c60176b12-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":null,"section":"5.1 Test system configuration","anchor_text":"he assumption that the supply is stable in 1 h. Fig. 3c is the total energy ly supply and demand. In","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"In price setting, the sellers are forbidden to buy from the grid and sell to the P2P market simultaneously and the time-and-level-of-use price is higher than the feed-in tariff, otherwise, an arbitrage opportunity arises."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-4c60176b12-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1 Seller’s problem","anchor_text":"Applied Energy 308 (2022) 118400 of energy sellers, energy buyers, and market equilibrium are presen","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In our model, the P2P market consists of energy buyers and sellers. Let S denote the set of energy sellers, with the typical energy seller s ∈ S. Let B denote the set of energy buyers, with the typical energy seller b ∈ B. The operational problem is solved during multi-periods and T is the set of all periods. t ∈ T is a typical single period with an equal duration of Δt."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-4c60176b12-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1 Seller’s problem","anchor_text":"gy , pi to decision-making problem can be cast as ∑ ∑ ∑ ∑ e. max : ( ρtsbptsb + λtsell(Pts − ptsb) −","equation_id":"(2)-(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"s.t. \\sum_{b\\in B}p^{t}_{sb}\\leqslant P^{t}_{s} : \\upsilon^{t}_{s}, \\forall t\\in T \\quad (2)\np^{t}_{sb}\\geqslant 0 : \\omega^{t}_{sb}, \\forall b\\in B, \\forall t\\in T \\quad (3)"},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-4c60176b12-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1 Seller’s problem","anchor_text":"gy , pi to decision-making problem can be cast as ∑ ∑ ∑ ∑ e. max : ( ρtsbptsb + λtsell(Pts − ptsb) −","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"where p^{t}_{sb} and \\rho^{t}_{sb} are decision variables. p^{t}_{sb} is the transaction amount between seller s and buyer b in period t. \\rho^{t}_{sb} is transaction price associated with p^{t}_{sb}. However, the market-clearing price \\rho^{t}_{sb} is out of control of seller s and buyer b but is determined by the market equilibrium problem of the game. Parameter P^{t}_{s} is the renewable energy for sale of seller s in period t. Parameter \\lambda^{t}_{sell} is FiT when a seller sells its energy to the power grid. Parameter \\lambda^{t}_{cost} is the P2P transaction cost, including network tariff for using the physical grid facilities and aggregator service fee."},{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-4c60176b12-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2 Buyer’s problem","anchor_text":"he ergy buyers in the P2P market. The second term is the revenue of selling an energy to the power g","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"For each rational energy buyer b ∈ B, it minimizes energy cost and the decision-making problem can be cast as\nmin : \\sum_{t\\in T}\\left(\\sum_{s\\in S}\\rho^{t}_{sb}p^{t}_{sb}+\\lambda^{t}_{buy}p^{t}_{bg}\\right)\\Delta t \\quad (4)"},{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-4c60176b12-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2 Buyer’s problem","anchor_text":"he ergy buyers in the P2P market. The second term is the revenue of selling an energy to the power g","equation_id":"(5)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"s.t. \\sum_{s\\in S}p^{t}_{sb}+p^{t}_{bg}+p^{t}_{bd}=D^{t}_{b}+p^{t}_{bc} : \\gamma^{t}_{b}, \\forall t\\in T \\quad (5)\np^{t}_{bg}\\geqslant 0 : \\omega^{t}_{bg}, \\forall t\\in T \\quad (6)"},{"evidence_id":"v141-b-g01-E17","location":{"location_id":"src-4c60176b12-p05-c2r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2 Buyer’s problem","anchor_text":"is s∈S he ptbg⩾0 : ωtbg, ∀t ∈T (6)nd ES λbtbuy = λtbuy0 + ktptbg, ∀t ∈T (7) a ptbc⩽pu, ptbd⩽pu, ∀t ∈","equation_id":"(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"\\lambda^{t}_{buy} = \\lambda^{t}_{buy0} + k^{t}p^{t}_{bg}, \\forall t\\in T \\quad (7)"},{"evidence_id":"v141-b-g01-E21","location":{"location_id":"src-4c60176b12-p02-c1r2__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"Indices and sets V B Set of energy buyers pts S Set of energy sellers b The index of energy buyers ρ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Indices and sets B Set of energy buyers S Set of energy sellers b The index of energy buyers s The index of energy sellers T Set of time periods t Index of time periods Parameters \\Delta t Duration of period \\lambda^{t}_{sell} Feed-in Tariff in period t \\lambda^{t}_{cost} P2P transaction cost in period t \\lambda^{t}_{buy} The TLOU price of energy buyer b in period t \\lambda^{t}_{buy0} Initial electricity price in TLOU in period t k^{t} Constant coefficient in TLOU P^{t}_{s} The energy supply of seller s in period t D^{t}_{b} The energy demand of buyer b in period t \\eta_{c} Charging efficiency \\eta_{d} Discharging efficiency p^{u} Maximal charging/discharging power Q^{0}_{b} Initial energy storage level of buyer b Q_{m} Capacity of the shared energy storage units Variables p^{t}_{sb} P2P transaction amount between seller s and buyer b in period t \\rho^{t}_{sb} P2P transaction price between seller s and buyer b in period t p^{t}_{bg} Energy from the grid of buyer b in period t p^{t}_{bc} Charging power of buyer b in period t p^{t}_{bd} Discharging power of buyer b in period t Q_{b} Capacity allocation of buyer b Q^{t}_{b} Energy storage level of buyer b in period t"},{"evidence_id":"v141-b-g02-e024","location":{"location_id":"src-4c60176b12-p06-c2r3__v141-a-M01-pricing","page":6,"printed_page":null,"section":"3.3 Peer-to-peer market equilibrium problem","anchor_text":"For the first game, energy sellers want to maximize energy revenues ss and will increase the P2P tra","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"For the first game, energy sellers want to maximize energy revenues and will increase the P2P transaction price \\rho_{sb}^{t}. In contrast, energy buyers aim to minimize energy costs and will lower the P2P transaction price \\rho_{sb}^{t}. Considering the bargain between energy sellers and buyers in the P2P market, the transaction between peers can be described as a non-cooperative game. The first game equilibrium exists when considering energy sellers and buyers’ optimal problems simultaneously. The P2P transaction price \\rho_{sb}^{t} is an endogenous variable, which is not determined by a single participant unilaterally, but obtained from the market equilibria according to the supply and demand relationship. So the P2P transaction price can reflect the value of energy resources."},{"evidence_id":"v141-b-g02-e028","location":{"location_id":"src-4c60176b12-p07-c1r2__v141-a-M01-coordination","page":7,"printed_page":null,"section":"4.1 KKT conditions","anchor_text":"Fig. 2. Market equilibrium consists of two games: a non-coopera global storage capacity constraint. ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"In equilibrium problem (26), energy seller s and buyer b have consistent decision variables p_{sb}^{t} and \\rho_{sb}^{t} because of the P2P transaction. However, the product term \\rho_{sb}^{t}p_{sb}^{t} in decision-making problem (1) and (15) makes the problem nonconvex. Besides, the transaction price \\rho_{sb}^{t} is an endogenous variable beyond the control of single energy seller s or buyer b, which is determined from the market equilibrium condition. So the equilibrium problem (26) is not a Nash-type game. To explain how the market equilibrium arises and how the P2P transaction price is obtained, we formulate the KKT conditions of the equilibrium problem (26) in this section. Since transaction price \\rho_{sb}^{t} is an endogenous variable and derived from market equilibrium, we regard it as a parameter while obtaining the KKT conditions of energy sellers and buyers. If we consider the optimization problem (1) and (15) from this perspective, the initial objective function is a linear program and the KKT condition of the linear program is necessary and sufficient. After getting the KKT conditions of all participants, we concatenate all KKT conditions and get an equilibrium problem of KKT conditions."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E06","quote":"Each energy buyer, whose goal is to minimize the expenditure on energy purchase, can buy energy from the P2P market or power grid depending on the price signal."}],[{"evidence_id":"v141-b-g01-E03","quote":"Energy sellers and buyers in the P2P market can trade with each other freely and reach a bilaterally satisfactory transaction result."}],[{"evidence_id":"v141-b-g02-e040","quote":"In price setting, the sellers are forbidden to buy from the grid and sell to the P2P market simultaneously"}]],"C2_formalization":{"graph_sha256":"8a0a9542b6f5925cd19a85ae73b0e8fcad2f3516995a30b6d23d83fcc696cce0","applicability":"formalized","reason":"The frozen R004 rule has one source-supported algebraic element in scope: the buyer's energy-cost minimization over P2P purchase p^t_sb and grid purchase p^t_bg, dependent on the P2P price signal rho^t_sb and TLOU price lambda^t_buy (C001, source Eq. (4)). C002 (free bilateral exchange) and C003 (seller prohibition on simultaneous grid purchase and P2P sale) remain qualitative/procedural: the supplied R004 evidence states permissions/prohibitions, and no seller-side grid-purchase variable is defined for C003. The P2P price rho is listed as a market variable in the paper but is explicitly endogenous/out of individual control and treated as a parameter in participant KKT problems; it is scoped here as a theta for the individual buyer's execution decision. All B evidence IDs are unreviewed candidate support, not independently source-audited.","bindings":[{"object_id":"v141-c-R004-x-p_sb","node_ids":["execution.energy_trade"],"edge_ids":["v141-c-R004-E001"],"rationale":"p^t_sb is the P2P purchase amount chosen in the buyer's cost-minimization; the frozen edge E001 records that this execution decision is conditional_on the price signal."},{"object_id":"v141-c-R004-x-p_bg","node_ids":["execution.energy_trade"],"edge_ids":["v141-c-R004-E001"],"rationale":"p^t_bg is the buyer's grid-purchase amount in the same execution decision; E001 is the frozen price-conditioned execution relation that the buyer evaluates alongside P2P purchase."},{"object_id":"v141-c-R004-theta-rho","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R004-E001"],"rationale":"rho^t_sb is the P2P price signal appearing in the buyer's cost expression. The source says it is endogenous and not controlled by a single participant, and its KKT treatment makes it parameter-like for the individual decision represented by E001."},{"object_id":"v141-c-R004-theta-lambda_buy","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R004-E001"],"rationale":"lambda^t_buy is the TLOU grid price signal compared by the buyer with the P2P price signal; E001 records the conditional dependence of energy trade on price signals."},{"object_id":"v141-c-R004-theta-Delta_t","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Delta_t scales the per-period P2P and grid energy cost in the buyer's execution decision; it is a timing parameter, not a price-conditioned graph edge."},{"object_id":"v141-c-R004-C001","node_ids":["execution.energy_trade","coordination.price_signal"],"edge_ids":["v141-c-R004-E001"],"rationale":"The source objective in Eq. (4) formalizes the buyer's P2P-versus-grid purchase cost decision under price signals; this is exactly the frozen conditional_on edge from execution.energy_trade to coordination.price_signal."},{"object_id":"v141-c-R004-C002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Free bilateral exchange is a procedural execution permission stated in the source and mapped to the energy-trade node; no separate frozen edge encodes it."},{"object_id":"v141-c-R004-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The prohibition on simultaneous seller grid purchase and P2P sale is a procedural restriction on energy-trade execution. The supplied source and frozen graph define no seller-side grid-purchase variable for an algebraic transcription, so this remains not_formalized."}],"revision_requests":["B re-extraction/definition request for C003: to express the seller no-simultaneous grid-purchase/P2P-sale restriction algebraically, a source-defined seller-side grid-purchase decision symbol and domain are required; the supplied text states only the prohibition.","If the arbitrage-prevention clause accompanying C003 is to be formalized, confirm whether TLOU means lambda^t_buy, lambda^t_buy0, or another buyer-indexed TLOU price, and whether the inequality is asserted for all b and t; no such indexed inequality is asserted here."]}},"quarantined_references":[]}});
